/**
 * Port defaults and validation shared by the repository and published launchers.
 */
/**
 * The default port for the dev shell, all blocks, and hot reload.
 * By default, the dev shell starts on this port.
 * If this port is occupied, the launcher tries higher ports in sequence until it finds an available port.
 * The --port option overrides this value and disables automatic port selection.
 */
export const DEFAULT_DEV_SHELL_PORT = 9873;
/** Highest valid TCP port. */
const MAX_PORT = 65535;
/** Parse and validate a named CLI port option. */
export function parsePort(name, raw) {
    const port = Number(raw);
    if (!Number.isInteger(port) || port <= 0 || port > MAX_PORT) {
        throw new Error(`${name} requires a port number, got "${raw}".`);
    }
    return port;
}
